insert into mark_scheme_points(mark_scheme_id,group_id,code,text,marks,accept,reject,requires,is_bod,sort_order) select e.msid,ig.id,p.code,p.txt,p.marks,'[]','[]',p.requires,false,p.sort_order from e59 e join p59 p on p.family=e.family left join ig59 ig on ig.mark_scheme_id=e.msid and ig.label=p.gl;
