-- Source-backed C1 normalization for explicit section caps and linked Cambridge mark points.
-- One-point/no-group manual wrappers only; usage-gated. Expansion points preserve dependencies.

create temp table t59(year int,series text,component int,variant int,path text,expected_marks int,family text) on commit drop;
create temp table g59(family text,label text,n_required int,marks_per_point int,max_marks int,award_mode text,sort_order int) on commit drop;
create temp table p59(family text,code text,txt text,gl text,marks int,requires jsonb,sort_order int) on commit drop;
create temp table r59 on commit drop as select t.*,q.id qid,ms.id msid from t59 t join source_papers sp on sp.year=t.year and sp.series::text=t.series and sp.variant=t.variant and sp.kind='QP'::paper_kind join components c on c.id=sp.component_id and c.number=t.component join questions q on q.source_paper_id=sp.id and q.path=t.path and q.marks=t.expected_marks join mark_schemes ms on ms.question_id=q.id and ms.max_marks=t.expected_marks;
create temp table e59 on commit drop as select r.* from r59 r where (select count(*) from mark_scheme_points p where p.mark_scheme_id=r.msid)=1 and (select count(*) from mark_scheme_groups g where g.mark_scheme_id=r.msid)=0 and exists(select 1 from mark_schemes ms where ms.id=r.msid and ms.scheme_type='manual_only'::scheme_type) and not exists(select 1 from assignment_questions aq where aq.question_id=r.qid) and not exists(select 1 from answers a where a.question_id=r.qid) and not exists(select 1 from grading_points gp join mark_scheme_points p on p.id=gp.mark_scheme_point_id where p.mark_scheme_id=r.msid) and not exists(select 1 from error_patterns ep join mark_scheme_points p on p.id=ep.mark_scheme_point_id where p.mark_scheme_id=r.msid) and not exists(select 1 from flashcards f join mark_scheme_points p on p.id=f.source_mark_scheme_point_id where p.mark_scheme_id=r.msid);
delete from mark_scheme_points p using e59 e where p.mark_scheme_id=e.msid;
create temp table ig59 on commit drop as with x as (insert into mark_scheme_groups(mark_scheme_id,label,n_required,marks_per_point,max_marks,sort_order,award_mode) select e.msid,g.label,g.n_required,g.marks_per_point,g.max_marks,g.sort_order,g.award_mode from e59 e join g59 g on g.family=e.family returning id,mark_scheme_id,label) select * from x;
update mark_schemes ms set scheme_type=case when e.family='addrcompare' then 'all_required'::scheme_type else 'any_n_from_m'::scheme_type end,prompt_version='atomic-source-c1-sections-0059-v1',updated_at=now() from e59 e where ms.id=e.msid;
